// Beta: same Helix call as checkBotIsMod(), but returns 'mod', 'not', 'expired'
// (Twitch rejected the token, so the sign-in has expired) or 'unknown' (any
// other failure), so a failed check is never shown as "not a moderator".
function beta_bot_mod_check($broadcasterId, $authToken, $clientID) {
  if (empty($authToken)) return 'expired';
  $ch = curl_init('https://api.twitch.tv/helix/moderation/moderators?broadcaster_id=' . urlencode((string)$broadcasterId));
  curl_setopt($ch, CURLOPT_RETURNTRANSFER, true);
  curl_setopt($ch, CURLOPT_HTTPHEADER, ['Authorization: Bearer ' . $authToken, 'Client-ID: ' . $clientID]);
  curl_setopt($ch, CURLOPT_TIMEOUT, 5);
  $response = curl_exec($ch);
  $httpCode = curl_getinfo($ch, CURLINFO_HTTP_CODE);
  if ($httpCode === 401) return 'expired';
  if ($response === false || $httpCode !== 200) { error_log("Beta mod check failed. HTTP Code: $httpCode"); return 'unknown'; }
  $data = json_decode($response, true);
  if (!is_array($data) || !isset($data['data']) || !is_array($data['data'])) return 'unknown';
  foreach ($data['data'] as $mod) { if (($mod['user_id'] ?? '') === '971436498') return 'mod'; }
  return 'not';
}
